// TH18 v1.00a Extra / stage07 道中波次 th18_s7_w06
// 源：st07.ecl.txt::MainSub05:1290-1304（创建排程）
//     st07.ecl.txt::GirlD01:718-741（敌本体运动与 8 连发上下文）
//     st07.ecl.txt::GirlD01_at:743-767（发射器与 EX）
// 入口为 stage main 调用的 MainFront→MainSub05；调用者 owner 是 STAGE(0,0)，
// 故 enmCreate 相对坐标即世界坐标（x 不套 TH06 的减 192）。
const TIME_LIMIT: int = 2780;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0,19,1)：TH18 type19 BIG_BALL2，色号 1（行基址 656）。
const TH18_BIG_BALL2: int = 656;

// 源 GirlD01_at:753-756 的逐弹 EX 链：
//   ANIM a=1 出生退位移 -4*初速，已并入 sh_dist；
//   BRIGHT 为纯表现，省略；
//   WAIT a=120 停住 EX 游标；
//   VELTIME a=60, r=4.0, s=当前弹角（s<=-999990 保留角），标量速 0.6->4.0。
// 出生减速/无判定窗口按公共口径省略；这里保留 WAIT 与速度斜坡本身。
xformdef GIRL_BULLET {
    wait(120);
    step_speed(4fx, 60);
}

// 源 GirlD01_at:743-767。源 @GirlD01_at 与本体主任务同帧启动；
// 目标 spawn 的弹任务出生次帧首跑，故用 wait(59) 把首发对齐到本体脚本 t=60。
async sub girl_fire() {
    wait(59);
    sh_reset(0);
    // 源 etSprite(0,19,1)
    sh_sprite(0, TH18_BIG_BALL2, 1);
    // 源 etAim(0,2)：自机狙环；etCount(0,32,1)、etAngle(0,0,0.698)：
    // M=1 时 q*delta 恒为 0，第二种角不参与首层几何，保留 32 路整环。
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 32, 1);
    sh_angle(0, 0deg, 0deg);
    // 源 etSpeed(0,0.6,1.6)：M=1 只用 s0。
    sh_speed(0, 0.6fx, 0fx);
    // 源 etDist(0,16) 与 ANIM 退位移 -4*0.6：沿每弹角度净推出 13.6px。
    sh_dist(0, 13.6fx);
    sh_xform(0, GIRL_BULLET);
    // 源 $A=8 的循环：t=60,130,...,550 共 8 波，每波间隔 70。
    for i in 0..8 {
        sh_fire(0);
        wait(70);
    }
}

// 源 GirlD01:718-741。判定：setHurtbox(32,32)->r=16；setHitbox(24,24)->r=12。
// 无敌为训练外壳；体碰按源普通圆框保留。
async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // 源 moveVel(pi/2,3) 后 moveVelTime(60,1,pi/2,0)：mode1=t^2。
    // 90deg 即 +y（向下）由 -48 进入画面。
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_fire();
    // 源 wait(400) 后 moveSpeedTime(120,1,2.0)，再 wait(60) 进入永久等待。
    wait(400);
    move_speed(120, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// 源 MainSub05:1292-1302：0/300/600/900 帧分别创建 1/2/2/3 只 GirlD01。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, 1600, 0, 1000, 0, girl_main);
    wait(300);
    _ = spawn_enemy(160fx, -48fx, 1600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(0fx, -48fx, 1600, 0, 1000, 0, girl_main);
    wait(300);
    _ = spawn_enemy(0fx, -48fx, 1600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(-160fx, -48fx, 1600, 0, 1000, 0, girl_main);
    wait(300);
    _ = spawn_enemy(0fx, -48fx, 1600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(100fx, -48fx, 1600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(-100fx, -48fx, 1600, 0, 1000, 0, girl_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    var rank: int = global(GVAR_RANK);
    if rank != RANK_EXTRA {
        loop { wait(600); }
    }
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
